import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;

public class Main {
    static byte[] data;
    static int pos = 0;

    static boolean skipSpace() {
        while (pos < data.length && (data[pos] & 0xff) <= ' ') pos++;
        return pos < data.length;
    }

    static String token() {
        skipSpace();
        int s = pos;
        while (pos < data.length && (data[pos] & 0xff) > ' ') pos++;
        return new String(data, s, pos - s, java.nio.charset.StandardCharsets.UTF_8);
    }

    static long num() {
        skipSpace();
        boolean neg = false;
        if (pos < data.length && (data[pos] == '-' || data[pos] == '+')) neg = data[pos++] == '-';
        long v = 0;
        while (pos < data.length && data[pos] >= '0' && data[pos] <= '9') v = v * 10 + (data[pos++] - '0');
        return neg ? -v : v;
    }

    public static void main(String[] args) throws Exception {
        data = System.in.readAllBytes();
        long n = num();
        // Primes up to 46340 cover every factor a 32-bit value can need (46340^2 < 2^31).
        int limit = 46340;
        boolean[] composite = new boolean[limit + 1];
        for (int p = 2; p * p <= limit; p++)
            if (!composite[p])
                for (int q = p * p; q <= limit; q += p) composite[q] = true;
        List<Integer> primes = new ArrayList<>();
        for (int p = 2; p <= limit; p++)
            if (!composite[p]) primes.add(p);
        HashMap<Long, Boolean> cache = new HashMap<>();
        StringBuilder out = new StringBuilder();
        for (long i = 0; i < n; i++) {
            long v = num();
            Boolean ok = cache.get(v);
            if (ok == null) {
                ok = v >= 2;
                for (int k = 0; ok && k < primes.size() && (long) primes.get(k) * primes.get(k) <= v; k++)
                    if (v % primes.get(k) == 0) ok = false;
                cache.put(v, ok);
            }
            if (i > 0) out.append('\n');
            out.append(ok ? "Prime" : "Composite");
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := num()
	// Primes up to 46340 cover every factor a 32-bit value can need (46340^2 < 2^31).
	const limit = 46340
	composite := make([]bool, limit+1)
	for p := 2; p*p <= limit; p++ {
		if !composite[p] {
			for q := p * p; q <= limit; q += p {
				composite[q] = true
			}
		}
	}
	primes := []int64{}
	for p := 2; p <= limit; p++ {
		if !composite[p] {
			primes = append(primes, int64(p))
		}
	}
	cache := map[int64]bool{}
	out := []byte{}
	for i := int64(0); i < n; i++ {
		v := num()
		ok, seen := cache[v]
		if !seen {
			ok = v >= 2
			for k := 0; ok && k < len(primes) && primes[k]*primes[k] <= v; k++ {
				if v%primes[k] == 0 {
					ok = false
				}
			}
			cache[v] = ok
		}
		if i > 0 {
			out = append(out, '\n')
		}
		if ok {
			out = append(out, "Prime"...)
		} else {
			out = append(out, "Composite"...)
		}
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
